mapper.select:
SELECT C.DOMAIN_ID , C.COMPANY_CD , C.TASK_ID , C.CHECK_ID , C.CHECK_NM , C.CHECK_YN FROM CHECKLIST_MASTER C
C.DOMAIN_ID = #{domainId} AND C.TASK_ID = #{taskId}
